using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Xml.Linq;
namespace V15Voice {
public static class RenderCheckpoint {
 public static string Profile(KokoroEngine e,RenderOptions o){string breaths="";if(o.Breathing==BreathMode.Auto){string path=Path.Combine(e.Root,"breaths");if(Directory.Exists(path))breaths=String.Join("|",Directory.GetFiles(path,"*.wav").OrderBy(x=>x,StringComparer.Ordinal).Select(StateFiles.Hash));}return SpeechArchive.Hash("stage215-v2|"+AudioRepair.Signature(e,o)+"|"+breaths+"|"+Tempo.Minimum(o)+"|"+Tempo.Maximum(o));}
 static string Folder(AnchorStage s,KokoroEngine e,RenderOptions o,BreathState before){string root=String.IsNullOrEmpty(o.CheckpointRoot)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"V15VoiceStudio","stage-checkpoints"):o.CheckpointRoot;return Path.Combine(root,SpeechArchive.Hash(Profile(e,o)+"|"+AiRepairSession.SnapshotHash(s.Cues)+"|"+before.Key));}
 public static AiMeasurement Read(AnchorStage s,KokoroEngine e,RenderOptions o,BreathState before){try{string folder=Folder(s,e,o,before);var x=StateFiles.Read(Path.Combine(folder,"stage.xml"));var m=AiRepairSession.ReadMeasurement(x);if(m!=null&&m.Valid&&m.Fits&&m.BeforeBreath.Key==before.Key&&Math.Abs(m.After-s.Budget)<.0001)return m;}catch{}return null;}
 public static void Write(AnchorStage s,KokoroEngine e,RenderOptions o,AiMeasurement m){if(!m.Fits||!m.Valid)return;string folder=Folder(s,e,o,m.BeforeBreath);Directory.CreateDirectory(folder);var copy=AiRepairSession.ReadMeasurement(AiRepairSession.MeasurementXml("stage",m));string stem=Guid.NewGuid().ToString("N");copy.Audio=Path.Combine(folder,stem+".wav");copy.NaturalAudio=Path.Combine(folder,stem+"-natural.wav");File.Copy(m.Audio,copy.Audio);File.Copy(m.NaturalAudio,copy.NaturalAudio);StateFiles.Write(Path.Combine(folder,"stage.xml"),AiRepairSession.MeasurementXml("stage",copy));}
 public static AiMeasurement FromSession(AnchorStage s,KokoroEngine e,RenderOptions o,BreathState before){if(o.AiRepair==null)return null;var r=o.AiRepair.Rows.FirstOrDefault(x=>x.Stage.Cues.Select(c=>c.Id).SequenceEqual(s.Cues.Select(c=>c.Id)));if(r==null||AiRepairSession.SnapshotHash(r.CurrentWords)!=AiRepairSession.SnapshotHash(s.Cues))return null;var m=r.CurrentMeasure;return m!=null&&m.Valid&&m.Fits&&m.ProfileSignature==Profile(e,o)&&m.BeforeBreath.Key==before.Key&&Math.Abs(m.After-s.Budget)<.0001?m:null;}
}
public sealed partial class VoiceRenderReport {
 public void VerifySourceUnchanged(){if(sourceHash.Length==64&&!String.IsNullOrEmpty(context.SourcePath)&&FileHash(context.SourcePath)!=sourceHash)throw new IOException("File nguồn thay đổi trong lúc render. Giữ checkpoint; mở lại nguồn trước khi xuất.");}
 public void ArtifactPublished(){Notify();}
 public void CachedStage(AnchorStage s,AiMeasurement m){PlanStageUnits(s.Number,new List<string>{s.Text});BeginUnit(s.Text,s.Number);Origin(true);if(Current!=null){Current.Before=m.Natural;Current.Tts=m.Tts;Current.PauseBefore=0;Current.PauseAfter=0;Current.Detail="Cache toàn chặng; chưa có mốc sau căn riêng từng cue.";}StageComponents(m.Tts,m.AppPauses,0,m.Breaths,m.Natural);if(CurrentStage!=null){CurrentStage.InnerPauses=CurrentStage.BetweenPauses=null;CurrentStage.AppPauses=m.AppPauses;}UnitBeforeStageDone();Step("CACHE","Dùng lại chặng đo đạt; không tổng hợp TTS hoặc căn lại chặng này.");}
}
}
